SELECT omur.member_id, m.member_name, omur.user_id, ompr.level_id, l.level_name FROM org_member m LEFT JOIN org_member_user_rel omur ON m.id = omur.member_id LEFT JOIN org_member_post_rel ompr ON m.id = ompr.member_id LEFT JOIN org_level l ON l.id = ompr.level_id WHERE m.id IN
#{memberId}
ORDER BY CASE WHEN ompr.default_flag = 1 THEN 1 -- 默认的排最前 WHEN ompr.default_flag = 2 THEN 2 -- 非默认的排第二 ELSE 3 -- 为空的排最后 END, ompr.id
